class WordFilter {
    struct Node {
        Node* children[27] = {};
        int weight = 0;
    };
    Node* root;
public:
    WordFilter(vector<string>& words) {
        root = new Node();
        for (int weight = 0; weight < words.size(); ++weight) {
            string w = words[weight];
            int n = w.size();
            for (int i = 0; i <= n; ++i) {
                string wrapped = w.substr(i) + "{" + w;
                Node* curr = root;
                curr->weight = weight;
                for (char ch : wrapped) {
                    int idx = ch - 'a';
                    if (ch == '{') idx = 26;
                    if (!curr->children[idx]) curr->children[idx] = new Node();
                    curr = curr->children[idx];
                    curr->weight = weight;
                }
            }
        }
    }

    int f(string pref, string suff) {
        Node* curr = root;
        string target = suff + "{" + pref;
        for (char ch : target) {
            int idx = ch - 'a';
            if (ch == '{') idx = 26;
            if (!curr->children[idx]) return -1;
            curr = curr->children[idx];
        }
        return curr->weight;
    }
};

class WordFilter {
    static class Node {
        Node[] children = new Node[27];
        int weight = 0;
    }
    private Node root;

    public WordFilter(String[] words) {
        root = new Node();
        for (int weight = 0; weight < words.length; weight++) {
            String w = words[weight];
            int n = w.length();
            for (int i = 0; i <= n; i++) {
                String wrapped = w.substring(i) + "{" + w;
                Node curr = root;
                curr.weight = weight;
                for (int j = 0; j < wrapped.length(); j++) {
                    char ch = wrapped.charAt(j);
                    int idx = ch == '{' ? 26 : ch - 'a';
                    if (curr.children[idx] == null) curr.children[idx] = new Node();
                    curr = curr.children[idx];
                    curr.weight = weight;
                }
            }
        }
    }

    public int f(String pref, String suff) {
        Node curr = root;
        String target = suff + "{" + pref;
        for (int i = 0; i < target.length(); i++) {
            char ch = target.charAt(i);
            int idx = ch == '{' ? 26 : ch - 'a';
            if (curr.children[idx] == null) return -1;
            curr = curr.children[idx];
        }
        return curr.weight;
    }
}

